--
-- Table structure for table `campus_events`
--

CREATE TABLE `campus_events` (
  `id` int NOT NULL,
  `title` varchar(255) NOT NULL,
  `type` varchar(50) DEFAULT 'academic',
  `status` varchar(50) DEFAULT 'upcoming',
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `start_time` time DEFAULT NULL,
  `end_time` time DEFAULT NULL,
  `location` varchar(255) DEFAULT 'Campus Wide',
  `description` text,
  `poster_url` varchar(255) DEFAULT NULL,
  `announcement` text
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

--
-- Dumping data for table `campus_events`
--

INSERT INTO `campus_events` (`id`, `title`, `type`, `status`, `start_date`, `end_date`, `start_time`, `end_time`, `location`, `description`, `poster_url`, `announcement`) VALUES
(9, 'Thesis Defended', 'academic', 'upcoming', '2026-04-22', '2026-04-22', '08:00:00', '17:00:00', '16', 'Thesis defended cutiiieeeee', 'assets/images/poster_1776699603_69e648d3d4521.jpg', 'defended yan sha'),
(14, 'BSCS Educational Tour and Workshops', 'academic', 'upcoming', '2026-04-28', '2026-04-28', '08:00:00', '17:00:00', '0', '💻✨ 𝗘𝘅𝗽𝗹𝗼𝗿𝗶𝗻𝗴 𝗕𝗲𝘆𝗼𝗻𝗱 𝘁𝗵𝗲 𝗖𝗹𝗮𝘀𝘀𝗿𝗼𝗼𝗺!\r\nThe 𝗕𝗦𝗖𝗦 𝗘𝗱𝘂𝗰𝗮𝘁𝗶𝗼𝗻𝗮𝗹 𝗧𝗼𝘂𝗿 & 𝗦𝗲𝗺𝗶𝗻𝗮𝗿-𝗪𝗼𝗿𝗸𝘀𝗵𝗼𝗽 𝟮𝟬𝟮𝟲 is set to take place on 𝗔𝗽𝗿𝗶𝗹 𝟮𝟴, 𝟮𝟬𝟮𝟲 at 𝗩𝗶𝗹𝗹𝗮 𝗔𝗹𝗳𝗿𝗲𝗱𝗼’𝘀 𝗥𝗲𝘀𝗼𝗿𝘁, 𝗦𝗮𝗻 𝗙𝗲𝗿𝗻𝗮𝗻𝗱𝗼 𝗖𝗶𝘁𝘆, 𝗣𝗮𝗺𝗽𝗮𝗻𝗴𝗮.\r\n\r\nThis academic activity aims to expand the knowledge and skills of BSCS students through meaningful discussions on 𝗛𝗮𝗰𝗸𝗮𝘁𝗵𝗼𝗻𝘀: 𝗧𝘂𝗿𝗻𝗶𝗻𝗴 𝗜𝗱𝗲𝗮𝘀 𝗶𝗻𝘁𝗼 𝗥𝗲𝗮𝗹𝗶𝘁𝘆 𝗮𝗻𝗱 𝗠𝗲𝗻𝘁𝗼𝗿𝘀𝗵𝗶𝗽 𝗶𝗻 𝗧𝗲𝗰𝗵: 𝗟𝗲𝗮𝗿𝗻𝗶𝗻𝗴 𝗳𝗿𝗼𝗺 𝗜𝗻𝗱𝘂𝘀𝘁𝗿𝘆 𝗘𝘅𝗽𝗲𝗿𝘁𝘀, giving students the opportunity to learn from real-world professionals in the field of technology.\r\n\r\nThrough this educational tour, students will gain valuable insights, industry exposure, and inspiration that will help them grow as future innovators, developers, and IT professionals. 🚀👨‍💻👩‍💻\r\n\r\n📍 Venue: Villa Alfredo’s Resort, Pampanga\r\n📅 Date: April 28, 2026\r\n💰 Fee: ₱3,890\r\n#BSCS #EducationalTour2026 #ComputerScienceSociety #FutureProgrammers #TechSeminar #SCC #BSCSCommunity #CSSociety #SCCCSS #kumsay #comsci #SayYesToCS #MakeItCSS🖌️💡\r\n\r\n🖌️ 𝙿𝙾𝚂𝚃𝙴𝚁 𝙱𝚈: 𝙹𝙷𝙾𝙽𝙰𝚂\r\n(𝘛𝘩𝘪𝘴 𝘱𝘰𝘴𝘵 𝘩𝘢𝘴 𝘣𝘦𝘦𝘯 𝘳𝘦𝘷𝘪𝘦𝘸𝘦𝘥 𝘢𝘯𝘥 𝘢𝘱𝘱𝘳𝘰𝘷𝘦𝘥 𝘣𝘺 𝘵𝘩𝘦 𝘊𝘚𝘚 𝘈𝘥𝘷𝘪𝘴𝘦𝘳𝘴.)', 'assets/images/poster_1776789575_69e7a84719ffc.jpg', 'Save the Date'),
(15, 'Basket Ball Game Day', 'sports', 'upcoming', '2026-04-23', '2026-04-23', '08:00:00', '17:00:00', '25', '𝗠𝗔𝗧𝗖𝗛 𝗗𝗔𝗬 | 𝗦𝗽𝗼𝗿𝘁𝘀𝗳𝗲𝘀𝘁 𝟮𝟬𝟮𝟲🏆\r\n\r\nThe games are set and the excitement begins!\r\nLet’s show our full support for our BSCS athletes as they compete, represent, and give their best on the court.\r\n\r\n📅 Check out the schedule below and cheer for BSCS!\r\nBasketball\r\n\r\n• BSCS vs BSHM (Seniors Division) 3:00 PM\r\n📍SCC Gymnasium\r\n#BSCS #Sportsfest2026 #MatchDay #CSSociety #SCCCSS #kumsay #comsci #SayYesToCS #MakeItCSS🖌️💡\r\n\r\n🖌️ 𝙿𝙾𝚂𝚃𝙴𝚁 𝙱𝚈: 𝙹𝙷𝙾𝙽𝙰𝚂\r\n(𝘛𝘩𝘪𝘴  𝘱𝘰𝘴𝘵 𝘩𝘢𝘴 𝘣𝘦𝘦𝘯 𝘳𝘦𝘷𝘪𝘦𝘸𝘦𝘥 𝘢𝘯𝘥 𝘢𝘱𝘱𝘳𝘰𝘷𝘦𝘥 𝘣𝘺 𝘵𝘩𝘦 𝘊𝘚𝘚 𝘈𝘥𝘷𝘪𝘴𝘦𝘳𝘴.)', 'assets/images/poster_1776789670_69e7a8a6ea71d.jpg', ''),
(16, 'MAKE-UP CLASS: System Fundamentals (elective) (BSCS 4C)', 'Academic', 'upcoming', '2026-04-30', '2026-04-30', '08:36:00', '10:43:00', 'Online', 'Temporary rescheduling of regular class. Attendance is required.', NULL, 'ATTENTION BSCS 4C:\r\n\r\nPlease be advised that our regular class for System Fundamentals (elective) (Session) will be temporarily rescheduled. \r\n\r\nPlease check your updated Calendar/Feed for the new date and room assignment. Attendance is strictly required.\r\n\r\nThank you.'),
(17, 'MAKE-UP CLASS: Human Computer Interaction (BSCS 4C)', 'Academic', 'upcoming', '2026-04-24', '2026-04-24', '15:33:00', '16:33:00', 'Online', 'Temporary rescheduling of regular class. Attendance is required.', NULL, 'ATTENTION BSCS 4C:\r\n\r\nPlease be advised that our regular class for Human Computer Interaction (Session) will be temporarily rescheduled. \r\n\r\nPlease check your updated Calendar/Feed for the new date and room assignment. Attendance is strictly required.\r\n\r\nThank you.');

